// Preact twins of the DS builders in components.ts (badge, layerCard, provenanceStrip) for the TSX shell.
// They render exactly the DOM that components.js builds; setLevel() from components.js still drives the card
// depth imperatively (the cockpit and the "Abrir tudo em Prova" button mutate .l3 nodes outside Preact).
// Source of truth: this .tsx file. ui.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment, render, type ComponentChildren, type VNode } from "../vendor/preact/preact.module.js";
import { PROV, nextLayerId, setLevel } from "./components.js";

/** Badge element. kind is val|est|sim|nd|ok|bad|warn; text overrides the label. */
export function Badge({ kind, text }: { kind: string; text?: string | null }): VNode {
  const p = PROV[kind];
  return <span class={"prov " + kind} title={p ? p.title : undefined}>{text || (p ? p.label : kind)}</span>;
}

export interface LayerProps {
  title: string; badge?: string; globalBadge?: string; answer?: ComponentChildren; why?: ComponentChildren;
  proof?: [string, ComponentChildren][]; level?: number; surface?: string;
}
/** Three-layer card (Resposta, Por quê, Prova). The id counter is shared with components.layerCard. */
export function LayerCard({ title, badge, globalBadge, answer, why, proof = [], level = 0, surface }: LayerProps): VNode {
  const id = nextLayerId();
  const lvl = Math.max(0, Math.min(2, level ?? 0));
  const showBadge = badge && badge !== globalBadge;
  return (
    <section class={"l3 " + (surface || "solid")} data-level={String(lvl)} aria-labelledby={id + "-t"}>
      <header><h2 class="h-card" id={id + "-t"}>{title}</h2>{showBadge ? <Badge kind={badge as string} /> : null}</header>
      <p class="l3-ans">{answer}</p>
      <div class="l3-why" id={id + "-why"}><span class="lbl-s">Por quê</span>{typeof why === "string" ? <p>{why}</p> : why}</div>
      <div class="l3-proof" id={id + "-proof"}><span class="lbl-s">Prova</span>
        <dl>{proof.map(([k, v]) => <Fragment><dt>{k}</dt><dd>{v}</dd></Fragment>)}</dl></div>
      <div class="l3-tabs" role="group" aria-label={"Profundidade do cartão " + title}>
        {["1 Resposta", "2 Por quê", "3 Prova"].map((label, i) => (
          <button type="button" aria-pressed={i === lvl} aria-controls={i === 0 ? undefined : id + (i === 1 ? "-why" : "-proof")}
            onClick={(e) => setLevel((e.currentTarget as HTMLElement).closest(".l3") as HTMLElement, i)}>{label}</button>
        ))}
      </div>
    </section>
  );
}

/** Provenance strip: one component instead of loose status chips. api is ok|off|unknown|null. */
export function ProvStrip({ items = [], api = null, note = null }: { items?: { kind: string; text: string }[]; api?: string | null; note?: string | null }): VNode {
  return (
    <div class="pstrip glass" role="status" aria-label="Procedência dos dados">
      <span class="k">Procedência</span>
      {items.map(it => <span class="it"><Badge kind={it.kind} />{it.text}</span>)}
      {api ? <span class="it">API:<span class={api === "ok" ? "api-ok" : "api-off"}>{api === "ok" ? "OK" : api === "off" ? "offline" : "verificando…"}</span></span> : null}
      {note ? <span class="it t3">{note}</span> : null}
    </div>
  );
}

/**
 * Render a view into the router outlet. The router empties the outlet (replaceChildren) before every route, so
 * any previous Preact tree is unmounted first: render(null) only removes nodes that are still attached.
 */
export function mount(outlet: HTMLElement, tree: ComponentChildren): void {
  render(null, outlet);
  outlet.replaceChildren();
  render(tree, outlet);
}
